            "revisionNotes": [
              {
                "title": "PATTERN: Axios Request Interceptor",
                "text": "api.interceptors.request.use(async (config) => { const token = await SecureStore.getItemAsync(\"token\"); if (token) config.headers.Authorization = `Bearer ${token}`; return config; });"
              },
              {
                "title": "PATTERN: Token Refresh on 401",
                "text": "Catch 401 -> call /auth/refresh -> update stored tokens -> update failed request header -> return api(originalRequest) to retry failed request seamlessly."
              },
              {
                "title": "RULE: AbortController on Unmount",
                "text": "const controller = new AbortController(); useEffect(() => { api.get(\"/data\", { signal: controller.signal }); return () => controller.abort(); }, []);"
              },
              {
                "title": "INTERVIEW TRAP: Storing Plain JWT in AsyncStorage",
                "text": "AsyncStorage is unencrypted on device storage. Always store sensitive access and refresh tokens in SecureStore / Keychain."
              },
              {
                "title": "COMMAND / CONFIGURATION: Timeout Configuration",
                "text": "Always configure explicit network timeouts (e.g. timeout: 15000) on mobile clients to prevent indefinitely hanging requests during subway tunnel signal loss."
              },
              {
                "title": "PRODUCTION NOTE: Retry-After Header",
                "text": "Implement exponential backoff with jitter on network 503/504 errors: delay = Math.min(1000 * 2 ** retryCount + Math.random() * 500, 30000)."
              }
            ]
